<?= view('layout/header',['title'=>'Staff']) ?><div class="top"><h1>Staff</h1><a class="btn" href="<?= site_url('staff/new') ?>">Add staff</a></div><table><tr><th>Avatar</th><th>Username</th><th>Full name</th><th>Actions</th></tr><?php foreach($users as $u): ?><tr><td><?php if($u['avatar']): ?><img class="thumb" src="<?= base_url('uploads/avatars/'.$u['avatar']) ?>"><?php endif ?></td><td><?= esc($u['username']) ?></td><td><?= esc($u['full_name']) ?></td><td><a href="<?= site_url('staff/edit/'.$u['id']) ?>">Edit</a> <a class="error" href="<?= site_url('staff/delete/'.$u['id']) ?>" onclick="return confirm('Delete this staff member?')">Delete</a></td></tr><?php endforeach ?></table><?= view('layout/footer') ?>
